package io.github.miklires.mevents.event;import static org.junit.jupiter.api.Assertions.*;import io.github.miklires.mevents.api.*;import java.util.List;import java.util.random.RandomGenerator;import org.junit.jupiter.api.Test;class EventCoreTest{@Test void lifecycleRejectsSkippingStates(){var machine=new EventStateMachine();assertTrue(machine.canMove(EventState.SCHEDULED,EventState.PREPARING));assertTrue(machine.canMove(EventState.ACTIVE,EventState.COMPLETED));assertFalse(machine.canMove(EventState.SCHEDULED,EventState.ACTIVE));assertThrows(IllegalStateException.class,()->machine.require(EventState.COMPLETED,EventState.ACTIVE));}@Test void selectionUsesWeights(){var a=new RewardDefinition("a",90,List.of("say a"));var b=new RewardDefinition("b",10,List.of("say b"));var def=new EventDefinition("drop","Drop",EventType.AIRDROP,"world",0,64,0,20,200,"ZOMBIE",100,List.of(a,b));assertEquals(a,new RewardSelector(new Fixed(.89)).select(def));assertEquals(b,new RewardSelector(new Fixed(.91)).select(def));}@Test void unsafeRewardCommandsAreRejected(){assertThrows(IllegalArgumentException.class,()->new RewardDefinition("bad",1,List.of("/op Alex")));assertThrows(IllegalArgumentException.class,()->new RewardDefinition("bad",1,List.of("say ok\nstop")));}@Test void automaticScheduleMustOutliveEvent(){var reward=new RewardDefinition("ok",1,List.of("say ok"));assertThrows(IllegalArgumentException.class,()->new EventDefinition("drop","Drop",EventType.AIRDROP,"world",0,64,0,100,200,0,"ZOMBIE",100,0,0,0,true,20,100,0,List.of(reward)));}record Fixed(double value)implements RandomGenerator{public long nextLong(){return 0;}public double nextDouble(double bound){return value*bound;}}}
